SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE cover_url=VALUES(cover_url),definition=VALUES(definition),category=VALUES(category),name=VALUES(name),description=VALUES(description),icon=VALUES(icon),sort=VALUES(sort),is_active=1;
UPDATE `template` SET is_active=0 WHERE id NOT IN ('wf-white-bg-2','wf-three-view','wf-face-swap','wf-outfit-fusion','wf-digital-model-1','wf-digital-model-2','wf-phone-shoot','wf-model-bag','wf-model-pants','wf-skirt-flat','wf-sport-duo-solo','wf-product-seeding-video','wf-clothing-talk-video','wf-solo-replica-video','wf-live-selling-video','wf-drive-transform-video','wf-clothing-fixed-video','wf-clothing-show-video','wf-content-replace-video','wf-kv-poster','wf-detail-cn','wf-detail-overseas','wf-hot-replica-main','wf-outfit-fusion-trial','wf-face-merge-trial','wf-detail-cn-trial','wf-model-bag-trial');
UPDATE `tier_def` SET features=JSON_SET(features,'$.templates',JSON_ARRAY('wf-outfit-fusion-trial','wf-face-merge-trial','wf-detail-cn-trial','wf-model-bag-trial')) WHERE tier_key='trial';
COMMIT;
